import{_ as s,a as r}from"./chunks/Pinia_full_screen.CrXGkRZm.js";import{_ as o,c as a,o as n,ah as e}from"./chunks/framework.RCw5T9E9.js";const b=JSON.parse('{"title":"Работа с Pinia Stores","description":"","frontmatter":{"title":"Работа с Pinia Stores"},"headers":[],"relativePath":"ru/store/general.md","filePath":"ru/store/general.md"}'),i={name:"ru/store/general.md"};function g(l,t,d,h,p,c){return n(),a("div",null,[...t[0]||(t[0]=[e('<h1 id="работа-с-pinia-stores" tabindex="-1">Работа с Pinia Stores <a class="header-anchor" href="#работа-с-pinia-stores" aria-label="Permalink to &quot;Работа с Pinia Stores&quot;">​</a></h1><p>Раздел <strong>Stores</strong> предназначен для просмотра зарегистрированных в приложении <strong>Pinia</strong>-сторов: имя (идентификатор), число полей <strong>state</strong> и <strong>getters</strong>, а после выбора строки — снимок <strong>state</strong> и <strong>getters</strong> с возможностью правок и записи обратно в приложение (в поддерживаемых случаях).</p><p>Подробнее про редактирование <strong>state</strong> и <strong>getters</strong>, а также про <strong>избранное</strong> по сторам:</p><ul><li><a href="/qa-tools/docs/ru/store/state.html">Работа со State</a></li><li><a href="/qa-tools/docs/ru/store/getters.html">Работа с Getters</a></li><li><a href="/qa-tools/docs/ru/store/favorite.html">Избранное</a></li></ul><h2 id="верхняя-панель-управления" tabindex="-1">Верхняя панель управления <a class="header-anchor" href="#верхняя-панель-управления" aria-label="Permalink to &quot;Верхняя панель управления&quot;">​</a></h2><p><img src="'+s+'" alt="Store, область заголовка"></p><h3 id="поиск-по-сторам" tabindex="-1">Поиск по сторам <a class="header-anchor" href="#поиск-по-сторам" aria-label="Permalink to &quot;Поиск по сторам&quot;">​</a></h3><p>Поле с подсказкой <strong>Search stores...</strong>. Активные критерии задаёт <strong>Search by</strong>. Те же флажки — первый блок <strong>Options → Pinia Store</strong>, под заголовком <strong>Search Settings</strong>: <strong>Search by store name</strong>, <strong>Search by key</strong>, <strong>Search by value</strong>. По умолчанию включено имя; key и value выключены. Изменение сразу действует на открытый список.</p><p>На <strong>Options → Pinia Store</strong> блоки идут так: <strong>Search Settings</strong>, затем <strong>Favorite Stores</strong>.</p><table tabindex="0"><thead><tr><th>Режим</th><th>Что использует список</th></tr></thead><tbody><tr><td><strong>Name</strong></td><td>отображаемое имя стора (<code>baseId</code>), в панели</td></tr><tr><td><strong>Key</strong></td><td>имена полей в <strong>state</strong> и <strong>getters</strong>, запрос к странице</td></tr><tr><td><strong>Value</strong></td><td>значения полей в <strong>state</strong> и <strong>getters</strong>, запрос к странице</td></tr></tbody></table><p>Непустой запрос оставляет стор, если совпал любой включённый режим. Если все три выключены, запрос не совпадает ни с чем.</p><p>Минимальная длина действует для всех режимов. По умолчанию <strong>2</strong> символа и задержка <strong>300 мс</strong>, из <strong>Options → General → Search Parameters</strong> (<a href="/qa-tools/docs/ru/options/update_settings.html">Параметры обновления</a>). Более короткий непустой запрос новый поиск не запускает: остаётся предыдущий результат, пока поле не очистят или запрос не достигнет минимума.</p><p><strong>Key</strong> и <strong>Value</strong> ниже этой длины страницу не спрашивают. Страница обходит state и getters до глубины 20 и возвращает не больше <strong>100</strong> сторов. Если запрос не удался, <strong>Key</strong> и <strong>Value</strong> ничего не находят; <strong>Name</strong> по-прежнему фильтрует в панели.</p><p><strong>Частичное и точное совпадение.</strong> Если запрос <strong>не</strong> обёрнут в кавычки, используется <strong>подстрока</strong> (без учёта регистра). <strong>Точное</strong> совпадение со всей строкой включается, если <strong>весь</strong> запрос обёрнут в <strong>двойные кавычки</strong> <code>&quot;...&quot;</code>.</p><h3 id="индикаторы-состояния" tabindex="-1">Индикаторы состояния <a class="header-anchor" href="#индикаторы-состояния" aria-label="Permalink to &quot;Индикаторы состояния&quot;">​</a></h3><p>Справа на панели <strong>Stores</strong> отображаются:</p><table tabindex="0"><thead><tr><th>Элемент</th><th>Назначение</th></tr></thead><tbody><tr><td><strong>N</strong> или <strong>N/M</strong></td><td><strong>N</strong> — видимые сторы. <strong>/M</strong> появляется только при непустом поле поиска и разных числах. <strong>M</strong> — последняя сводка.</td></tr><tr><td><strong>Избранное</strong> ★</td><td>Видимые избранные / всего сохранённых, или <code>0</code>, если список пуст. Жёлтый, когда хотя бы одна видимая строка в избранном. Клик открывает <strong>Options → Pinia Store → Favorite Stores</strong>.</td></tr><tr><td><strong>Обновление</strong></td><td><strong>Refresh</strong> (недоступна, пока идёт загрузка сводки) и локальное время последней успешной сводки, либо <code>Loading...</code>.</td></tr></tbody></table><p>Перед сводкой панель опрашивает страницу. Если ответ не пришёл, запрос сводки не отправляется: список пуст (<strong>No stores found</strong>), оверлея ошибки нет. Если сводка так и не пришла, через 3 секунды показывается <strong>Timeout: Pinia stores not found or not initialized</strong>. Неудачный запрос показывает <strong>Failed to load Pinia stores. Make sure Pinia is installed and initialized.</strong> Сообщение закрывает вкладку.</p><h2 id="рабочая-область" tabindex="-1">Рабочая область <a class="header-anchor" href="#рабочая-область" aria-label="Permalink to &quot;Рабочая область&quot;">​</a></h2><p><img src="'+r+`" alt="Pinia, полноэкранный режим"></p><h3 id="список-сторов" tabindex="-1">Список сторов <a class="header-anchor" href="#список-сторов" aria-label="Permalink to &quot;Список сторов&quot;">​</a></h3><p>Слева таблица сторов. Колонка <strong>Name</strong> видна всегда. Меню колонок переключает <strong>State</strong> и <strong>Getters</strong>; обе включены по умолчанию. Пустой список: <strong>No stores found</strong>.</p><ul><li><strong>Name</strong> — отображаемое имя стора (<code>baseId</code>) или <strong>Unknown Store</strong>, если имени нет;</li><li><strong>State</strong> — число ключей state или <strong>—</strong>, если их ноль;</li><li><strong>Getters</strong> — число getters или <strong>—</strong>, если их ноль.</li></ul><p>Любая строка открывает карточку. Избранные строки остаются сверху. Меню строки: <strong>Ask AI</strong> и <strong>Add favorite</strong> / <strong>Remove favorite</strong>. Звезда в строке делает то же переключение. См. <a href="/qa-tools/docs/ru/store/favorite.html">Избранное</a>.</p><p><strong>Ask AI</strong> доступен всегда. Он читает стор со страницы и прикрепляет state и getters. Если чтение не удалось, появляется уведомление <strong>Could not read the store {name}</strong>. Иначе открывается вкладка <strong>AI</strong>, над полем ввода появляется плашка, например <em>Store cart</em>: <strong>×</strong> убирает её из вопроса. Можно ввести вопрос или отправить плашку без текста. Если в <strong>Logs</strong> есть изменение этого стора, вложение называет последнее как <code>#N</code>. Значения маскируются по настройкам AI и обрезаются; если <strong>Values of store state, props, emits and actions</strong> выключено, ассистент получает только имена и типы.</p><h2 id="детализация-стора" tabindex="-1">Детализация стора <a class="header-anchor" href="#детализация-стора" aria-label="Permalink to &quot;Детализация стора&quot;">​</a></h2><p>Выбор строки открывает панель детализации. Если ничего не выбрано, она пишет <strong>Select a store to see details</strong>. Ниже <strong>1000</strong> px карточка закрывает список.</p><h3 id="сводная-информация" tabindex="-1">Сводная информация <a class="header-anchor" href="#сводная-информация" aria-label="Permalink to &quot;Сводная информация&quot;">​</a></h3><p>В верхней части панели отображаются:</p><ul><li>имя стора;</li><li><strong>State: N</strong>, если число ключей state больше нуля;</li><li><strong>Getters: N</strong>, если число getters больше нуля;</li><li>строка <strong>Updated:</strong>. Пока идёт первая загрузка, там <code>Loading...</code>. После успешного чтения — UTC <code>YYYY-MM-DD HH:mm:ss</code> (часы на панели инструментов локальные).</li></ul><h3 id="данные-стора" tabindex="-1">Данные стора <a class="header-anchor" href="#данные-стора" aria-label="Permalink to &quot;Данные стора&quot;">​</a></h3><p>Ниже доступны вкладки:</p><table tabindex="0"><thead><tr><th>Вкладка</th><th>Назначение</th></tr></thead><tbody><tr><td><strong>State</strong></td><td>снимок реактивного <strong>state</strong>; поддерживаются просмотр и сохранение изменений</td></tr><tr><td><strong>Getters</strong></td><td>снимок текущих значений <strong>getters</strong> в сериализованном виде; поддерживается просмотр и ограниченное редактирование</td></tr></tbody></table><p>Вкладка видна только если её счётчик больше нуля. Карточка открывается на <strong>State</strong>, если этот счётчик больше нуля, иначе на <strong>Getters</strong>. Пока снимок грузится, в теле написано <strong>Loading store data...</strong>. Пустой раздел: <strong>No state data</strong> или <strong>No getters data</strong>.</p><p>Данные активной вкладки отображаются в формате <strong>JSON</strong> — в текстовом или древовидном виде в зависимости от настроек инспектора.</p><h3 id="навигация" tabindex="-1">Навигация <a class="header-anchor" href="#навигация" aria-label="Permalink to &quot;Навигация&quot;">​</a></h3><ul><li>кнопка <strong>← Назад</strong> закрывает карточку, в том числе во время редактирования;</li><li><strong>Esc</strong> в режиме редактирования сбрасывает черновик и оставляет карточку открытой;</li><li><strong>Esc</strong> вне режима редактирования закрывает карточку.</li></ul><h3 id="элементы-управления" tabindex="-1">Элементы управления <a class="header-anchor" href="#элементы-управления" aria-label="Permalink to &quot;Элементы управления&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Элемент</th><th>Назначение</th></tr></thead><tbody><tr><td><strong>Star</strong></td><td>добавить или убрать стор из избранного. Подсказка: <strong>Add to favorites</strong> / <strong>Remove from favorites</strong></td></tr><tr><td><strong>Refresh</strong></td><td>перезапросить этот стор. Подсказка <strong>Refresh data</strong>. Недоступна, пока карточка загружается. Скрыта в режиме правки</td></tr><tr><td><strong>Edit</strong></td><td>режим правки активной вкладки. Подсказка <strong>Edit state</strong> или <strong>Edit getters</strong></td></tr></tbody></table><h3 id="режим-редактирования" tabindex="-1">Режим редактирования <a class="header-anchor" href="#режим-редактирования" aria-label="Permalink to &quot;Режим редактирования&quot;">​</a></h3><p>Порядок кнопок в режиме просмотра: <strong>Star → Refresh → Edit</strong>. После <strong>Edit</strong> кнопки <strong>Refresh</strong> и <strong>Edit</strong> заменяются на <strong>Cancel</strong> и <strong>Save</strong>. <strong>Star</strong> остаётся.</p><table tabindex="0"><thead><tr><th>До редактирования</th><th>В режиме редактирования</th></tr></thead><tbody><tr><td><strong>Refresh</strong></td><td><strong>Cancel</strong> — отмена изменений и выход из режима редактирования</td></tr><tr><td><strong>Edit</strong></td><td><strong>Save</strong> — применить изменения в приложение</td></tr></tbody></table><p><strong>Save</strong> неактивна, если JSON не разбирается. Изменения применяются только после <strong>Save</strong>. Отдельного уведомления нет. Если страница отклоняет запись, режим редактирования остаётся открытым, а ошибка пишется в консоль. При успехе режим редактирования закрывается, и сообщение о результате заново загружает снимок.</p><p>Для <strong>State</strong> используется обновление текущего состояния стора, для <strong>Getters</strong> — запись поддерживается только в допустимых сценариях; ограничения зависят от реализации конкретного стора.</p><p>Звезда <strong>избранного</strong> в этой панели и в таблице описана на странице <a href="/qa-tools/docs/ru/store/favorite.html">Избранное</a>.</p><p>Данные карточки соответствуют <strong>снимку на момент последнего запроса</strong>: внешние изменения в приложении не отражаются автоматически, пока вы не выполните <strong>Refresh</strong> в карточке или не обновите сводку на верхней панели вкладки <strong>Stores</strong>.</p><h2 id="ограничения-отображения" tabindex="-1">Ограничения отображения <a class="header-anchor" href="#ограничения-отображения" aria-label="Permalink to &quot;Ограничения отображения&quot;">​</a></h2><h3 id="ограничения-чтения-данных" tabindex="-1">Ограничения чтения данных <a class="header-anchor" href="#ограничения-чтения-данных" aria-label="Permalink to &quot;Ограничения чтения данных&quot;">​</a></h3><ol><li><strong>Сводка по всем сторам</strong> — лёгкий ответ: для каждого стора передаются идентификатор, имя, счётчики ключей <strong>state</strong> / <strong>getters</strong> и метка времени снимка, без полной сериализации значений.</li><li><strong>Карточка выбранного стора</strong> — отдельный запрос с сериализованными <strong>state</strong> и <strong>getters</strong> для отображения и редактирования.</li></ol><p>Сериализация <strong>state</strong> и <strong>getters</strong> ограничена разумными пределами глубины и размера: циклические структуры, функции и специальные объекты могут быть усечены или представлены иначе, чем в исходном runtime.</p><p>Поиск по <strong>Key</strong> и <strong>Value</strong> возвращает не больше <strong>100</strong> сторов и обходит значения до глубины 20.</p><h3 id="ограничение-объема-хранения" tabindex="-1">Ограничение объёма хранения <a class="header-anchor" href="#ограничение-объема-хранения" aria-label="Permalink to &quot;Ограничение объёма хранения&quot;">​</a></h3><p>Фиксированного лимита числа сторов в таблице нет: отображаются все сторы, возвращённые сводкой <strong>Pinia</strong> в типичном сценарии.</p><p>Нестандартные регистрации или крайние конфигурации могут отображаться неполно. Удастся ли запись, зависит от стора. Неудачное сохранение оставляет режим редактирования и пишется в консоль.</p><h2 id="принципы-работы" tabindex="-1">Принципы работы <a class="header-anchor" href="#принципы-работы" aria-label="Permalink to &quot;Принципы работы&quot;">​</a></h2><h3 id="когда-начинается-сбор-данных" tabindex="-1">Когда начинается сбор данных <a class="header-anchor" href="#когда-начинается-сбор-данных" aria-label="Permalink to &quot;Когда начинается сбор данных&quot;">​</a></h3><p>Модуль Pinia во внедрённом сценарии подключается после обнаружения <strong>Pinia</strong> на странице (логика сходна с вкладкой <strong>Props</strong>: сначала должны быть Vue и активный инспектор).</p><p>Если Pinia не установлена или ещё не инициализирована при открытии вкладки <strong>Stores</strong>, список будет пустым или появится сообщение об ошибке загрузки.</p><h3 id="что-попадает-в-мониторинг" tabindex="-1">Что попадает в мониторинг <a class="header-anchor" href="#что-попадает-в-мониторинг" aria-label="Permalink to &quot;Что попадает в мониторинг&quot;">​</a></h3><ol><li><strong>Сводка</strong> — только идентификаторы, имена и счётчики полей для таблицы.</li><li><strong>Детали одного стора</strong> — полный сериализованный <strong>state</strong> и <strong>getters</strong> по выбору пользователя.</li></ol><p>Так отделяется <strong>быстрый список</strong> от <strong>тяжёлого чтения</strong> одного стора.</p><h3 id="как-устроен-обмен" tabindex="-1">Как устроен обмен <a class="header-anchor" href="#как-устроен-обмен" aria-label="Permalink to &quot;Как устроен обмен&quot;">​</a></h3><p>Панель не читает Pinia напрямую: она отправляет сообщение в контекст страницы, где доступен реестр зарегистрированных сторов.</p><div class="language-js vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// Иллюстрация: запрос сводки — только id стора, имя и счётчики ключей</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> response</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> await</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> bridge.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">send</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">({ type: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;PINIA_GET_STORES_SUMMARY&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> })</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// response.summary — объект «storeId → { id, baseId, stateKeys, getterKeys, … }»</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> detail</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> await</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> bridge.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">send</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">({</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  type: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;PINIA_GET_STORE_STATE&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  storeId: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;my-store-id&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">})</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// detail.state, detail.getters — данные для отображения и редактирования</span></span></code></pre></div><p>Поиск по ключам и значениям (<code>PINIA_SEARCH</code>) выполняется на странице и возвращает только список идентификаторов подходящих сторов.</p><h2 id="см-также" tabindex="-1">См. также <a class="header-anchor" href="#см-также" aria-label="Permalink to &quot;См. также&quot;">​</a></h2><ul><li><a href="/qa-tools/docs/ru/store/state.html">Работа со State</a></li><li><a href="/qa-tools/docs/ru/store/getters.html">Работа с Getters</a></li><li><a href="/qa-tools/docs/ru/store/favorite.html">Избранное</a></li><li><a href="/qa-tools/docs/ru/options/update_settings.html">Параметры обновления и автообновление</a></li></ul>`,67)])])}const m=o(i,[["render",g]]);export{b as __pageData,m as default};
